#!/usr/bin/env python3
"""File units: every tracked source file belongs to exactly one reviewer.
Writes STATE/units.json and one prompt per unit. Run from anywhere:
REVIEW_DATE=YYYY-MM-DD review/units.py"""
import glob, json, os, subprocess
from cfg import REPO, STATE

os.chdir(REPO)
T = 'graphix-types/src/'; C = 'graphix-compiler/src/'; F = C + 'fusion/'; E = F + 'emit/'
NOMATCH = []


def g(*pats):
    out = []
    for p in pats:
        m = sorted(glob.glob(p, recursive=True))
        if not m: NOMATCH.append(p)
        out += m
    return out


def nl(fs): return sum(sum(1 for _ in open(f, errors='replace')) for f in fs)


U = []


def u(key, title, files, docs=(), focus='', ranges=None):
    U.append(dict(key=key, title=title, files=files, docs=list(docs), focus=focus, ranges=ranges or {}))


def parts(key, title, files, n, docs=(), focus=''):
    """n reviewers over a file list, balanced by lines."""
    bins = [[] for _ in range(n)]
    for f in sorted(files, key=lambda f: -nl([f])): min(bins, key=nl).append(f)
    for i, b in enumerate(bins):
        names = ', '.join(os.path.basename(f) for f in sorted(b, key=lambda f: -nl([f]))[:5])
        u(f'{key}-{chr(97 + i)}', f'{title}, part {i + 1} of {n} ({names}{" ..." if len(b) > 5 else ""})', sorted(b), docs, focus)


def ranged(key, title, f, n, docs=(), focus='', extra=()):
    """n reviewers over one large file, by line range; `extra` files go to the last."""
    total = nl([f]); step = -(-total // n)
    for i in range(n):
        a, b = i * step + 1, min(total, (i + 1) * step)
        u(f'{key}-{chr(97 + i)}', f'{title} (lines {a}-{b} of {total})',
          [f] + (list(extra) if i == n - 1 else []), docs, focus, {f: (a, b)})


