# CR claude for claude: [test-gap/low] EXTS has no 'vim', 'json' or 'toml', so the vim
# syntax files, the VS Code tmLanguage and language-configuration, and the helix/zed
# configs are in no unit and are never printed as uncovered. These regex highlighters
# have no gate, so review is their only check, and they have drifted: both color an
# identifier named `ok` as a constant and mark `\x..`/`\u{..}` string escapes that the
# parser refuses. Fix: add the three extensions (skipping the generated grammar.json,
# node-types.json and package-lock.json) and give the editor files to the ide-tooling
# unit. (ide-tooling-06)
EXTS = ('rs', 'gx', 'gxi', 'js', 'c', 'scm', 'py', 'sh', 'el', 'lua', 'ts', 'md')
SKIP = ('graphix-fuzz/findings', 'design/', 'docs/', 'ide/tree-sitter-graphix/src/parser.c')
allf = subprocess.run(['git', 'ls-files'], capture_output=True, text=True).stdout.split()
allf = [f for f in allf if f.rsplit('.', 1)[-1] in EXTS and not f.startswith(SKIP) and '/' in f
        and not f.endswith('build.rs')]
seen = {}
for x in U:
    x['lines'] = sum(r[1] - r[0] + 1 if (r := x['ranges'].get(f)) else nl([f]) for f in x['files'])
    for f in x['files']:
        if f in seen and f not in x['ranges']: print('TWICE', f, seen[f], x['key'])
        seen[f] = x['key']
print('no match', NOMATCH)
print('missing docs', sorted({d for x in U for d in x['docs'] if not os.path.exists('design/' + d)}))
print('uncovered', [f for f in allf if f not in seen])
print('units', len(U), 'lines', sum(x['lines'] for x in U))
for x in sorted(U, key=lambda x: -x['lines'])[:14]: print(' ', x['lines'], x['key'], len(x['files']))
json.dump(U, open(STATE + '/units.json', 'w'), indent=1)
for x in U:
    fl = '\n'.join(
        f'- {f} (lines {r[0]}-{r[1]} of {nl([f])}: yours; another reviewer has the rest, skim it for context)'
        if (r := x['ranges'].get(f)) else f'- {f} ({nl([f])} lines)' for f in x['files'])
    s = f"YOUR UNIT: {x['title']}\n\nFiles — read every line ({x['lines']} lines total):\n{fl}\n\n"
    if x['docs']:
        s += ('Design docs defining the rules this code implements: '
              + ', '.join('design/' + d for d in x['docs']) + '\n\n')
    if x['focus']: s += f"Focus: {x['focus']}\n\n"
    s += ('Follow calls into other files whenever correctness depends on them; a finding may cite a file '
          'outside your unit when you found it by tracing (give its exact file:line).\n')
    open(f"{STATE}/prompts/{x['key']}.md", 'w').write(s)
